describe('Username Pre-fill on Login Page', () => {
  const testUsername = 'testuser@example.com';
  const testPassword = 'SecurePassword123!';
  const loginUrl = 'http://localhost:3000/login';
  const dashboardUrl = 'http://localhost:3000/dashboard';

  beforeEach(() => {
    cy.clearLocalStorage();
    cy.clearCookies();
    cy.visit(loginUrl);
  });

  it('should pre-fill username field when user returns after previous login', () => {
    // First login - establish session
    cy.get('input[name="username"]').type(testUsername);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Verify successful login
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="user-profile"]').should('contain', testUsername);

    // Logout
    cy.get('[data-testid="logout-button"]').click();
    cy.url().should('include', loginUrl);

    // Return to login page
    cy.visit(loginUrl);

    // Verify username is pre-filled
    cy.get('input[name="username"]').should('have.value', testUsername);
    cy.get('input[name="password"]').should('have.value', '');
  });

  it('should handle pre-filled username and allow password entry for login', () => {
    // Simulate previous login by setting localStorage
    cy.window().then((win) => {
      win.localStorage.setItem('lastUsername', testUsername);
    });

    cy.visit(loginUrl);

    // Verify username is pre-filled from localStorage
    cy.get('input[name="username"]').should('have.value', testUsername);

    // Enter password and login
    cy.get('input[name="password"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Verify successful login
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="user-profile"]').should('be.visible');
  });

  it('should clear pre-filled username when user manually clears it', () => {
    // Set pre-filled username
    cy.window().then((win) => {
      win.localStorage.setItem('lastUsername', testUsername);
    });

    cy.visit(loginUrl);

    // Verify username is pre-filled
    cy.get('input[name="username"]').should('have.value', testUsername);

    // Clear the username field
    cy.get('input[name="username"]').clear();
    cy.get('input[name="username"]').should('have.value', '');

    // Type a different username
    const newUsername = 'newuser@example.com';
    cy.get('input[name="username"]').type(newUsername);
    cy.get('input[name="username"]').should('have.value', newUsername);
  });

  it('should not pre-fill username if localStorage is empty or corrupted', () => {
    // Ensure localStorage is clean
    cy.window().then((win) => {
      win.localStorage.removeItem('lastUsername');
    });

    cy.visit(loginUrl);

    // Verify username field is empty
    cy.get('input[name="username"]').should('have.value', '');
    cy.get('input[name="username"]').should('be.empty');
  });

  it('should handle special characters in pre-filled username', () => {
    const specialUsername = 'user+test@example.co.uk';

    cy.window().then((win) => {
      win.localStorage.setItem('lastUsername', specialUsername);
    });

    cy.visit(loginUrl);

    // Verify special characters are preserved
    cy.get('input[name="username"]').should('have.value', specialUsername);
    cy.get('input[name="username"]').invoke('val').should('equal', specialUsername);
  });

  it('should update stored username after successful login with different user', () => {
    const firstUsername = 'user1@example.com';
    const secondUsername = 'user2@example.com';

    // First login
    cy.window().then((win) => {
      win.localStorage.setItem('lastUsername', firstUsername);
    });

    cy.visit(loginUrl);
    cy.get('input[name="username"]').should('have.value', firstUsername);

    // Clear and login with different user
    cy.get('input[name="username"]').clear().type(secondUsername);
    cy.get('input[name="password"]').type(testPassword);
    cy.get('button[type="submit"]').click();

    // Verify login was successful
    cy.url().should('include', dashboardUrl);

    // Logout and verify new username is pre-filled
    cy.get('[data-testid="logout-button"]').click();
    cy.visit(loginUrl);

    cy.get('input[name="username"]').should('have.value', secondUsername);
  });
});
